  // js/staging/stagingFactory.js
  var STAGING_PRESETS = {
    primitive: primitivePresets,
    figure: figurePresets,
    architecture: architecturePresets,
    prop: propPresets
  };
  var StagingFactory = class _StagingFactory {
    constructor(app) {
      this.app = app;
    }
    static generateId() {
      return crypto.randomUUID ? crypto.randomUUID() : "stg_" + Date.now().toString(36) + Math.random().toString(36).slice(2);
    }
    /**
     * @param {'primitive'|'figure'|'architecture'|'prop'} kind
     * @param {string} presetId
     * @param {object} [params]
     * @param {string|number} [colorOverride]
     */
    create(kind, presetId, params = {}, colorOverride = null) {
      const registry = STAGING_PRESETS[kind];
      const preset = registry && registry[presetId];
      if (!preset) {
        console.warn(`Staging: unknown preset ${kind}/${presetId}`);
        return null;
      }
      const merged = { ...preset.params, ...params };
      const color = colorOverride ?? preset.defaultColor;
      const material = mat(color);
      const object = preset.create(merged, material);
      if (!object) return null;
      object.traverse((o) => {
        if (o.isMesh && o.material === void 0) o.material = material;
      });
      if (colorOverride != null) {
        object.traverse((o) => {
          if (o.isMesh && o.material && o.material.color) {
            if (o.material.color.getHex() === preset.defaultColor) o.material = material;
          }
        });
      }
      object.name = `${preset.label} ${_StagingFactory.generateId().slice(0, 4)}`;
      object.userData.type = "staging";
      object.userData.name = preset.label;
      object.userData.staging = {
        id: _StagingFactory.generateId(),
        kind,
        presetId,
        params: merged,
        colorOverride: colorOverride != null ? "#" + new Color(color).getHexString() : null
      };
      return object;
    }
    static getSeatMetadata(object) {
      if (!object) return null;
      if (object.userData && object.userData.seat) return object.userData.seat;
      let found = null;
      object.traverse((o) => {
        if (!found && o.userData && o.userData.seat) found = o.userData.seat;
      });
      return found;
    }
  };

  // js/staging/stagingManager.js
  var StagingManager = class {
    constructor(app) {
      this.app = app;
      this.factory = new StagingFactory(app);
    }
    /** All presets for UI panels: [{ kind, presetId, label }] */
    static listPresets() {
      const out = [];
      for (const [kind, registry] of Object.entries(STAGING_PRESETS)) {
        for (const [presetId, preset] of Object.entries(registry)) {
          out.push({ kind, presetId, label: preset.label });
        }
      }
      return out;
    }
    /**
     * Create and place a staging object at a world position (default origin).
     * @returns the created object or null
     */
    place(kind, presetId, { position = null, params = {}, colorOverride = null } = {}) {
      const object = this.factory.create(kind, presetId, params, colorOverride);
      if (!object) return null;
      if (position) object.position.copy(position);
      if (kind === "figure" && presetId === "figure-seated") {
        if (this._snapToChair(object, position)) {
        }
      }
      const command = new AddObjectCommand(this.app, object);
      this.app.historyManager.executeCommand(command);
      return object;
    }
    /**
     * Snap a seated figure onto the nearest chair under/within range.
     * Seat metadata: { height, yaw, offset } on the chair group.
     */
    _snapToChair(figure, dropPosition) {
      const searchCenter = dropPosition || figure.position;
      const radius = 1.2;
      let best = null, bestDist = Infinity;
      for (const candidate2 of this.app.objects) {
        if (!candidate2.userData || candidate2.userData.type !== "staging") continue;
        const st = candidate2.userData.staging;
        if (!st || st.kind !== "prop") continue;
        const seat2 = StagingFactory.getSeatMetadata(candidate2);
        if (!seat2) continue;
        const d = candidate2.position.distanceTo(searchCenter);
        if (dropPosition && d > radius) continue;
        if (d < bestDist) {
          bestDist = d;
          best = { candidate: candidate2, seat: seat2 };
        }
      }
      if (!best) return false;
      const { candidate, seat } = best;
      const offset = seat.offset || [0, 0, 0];
      const yaw = candidate.rotation.y + (seat.yaw || 0);
      const rotated = new Vector3(offset[0], offset[1], offset[2]).applyAxisAngle(new Vector3(0, 1, 0), candidate.rotation.y);
      figure.position.copy(candidate.position).add(rotated);
      figure.position.y = seat.height;
      figure.rotation.y = yaw;
      figure.userData.seatedOn = candidate.userData.staging?.id || candidate.uuid;
      return true;
    }
    /** Re-apply chair snap for an already-selected seated figure ("sit" action). */
    sitSelected() {
      const sel = this.app.selectedObject;
      if (!sel || !sel.userData?.staging) return false;
      const st = sel.userData.staging;
      if (st.kind !== "figure" || !st.presetId.startsWith("figure-seated")) return false;
      return this._snapToChair(sel, sel.position);
    }
    /** Convenience: add a preset button entry point used by the UI. */
    addFromUI(kind, presetId) {
      const placed = this.place(kind, presetId, {});
      if (placed && this.app.ui?.showNotification) {
        this.app.ui.showNotification(`Placed ${placed.name}`, "success");
      }
      return placed;
    }
  };

