  // js/staging/cameras/frustumRenderer.js
  init_three_module();
  function buildFrustumVisual(color) {
    const geometry = new BufferGeometry();
    const material = new LineBasicMaterial({ color, transparent: true, opacity: 0.9 });
    const lines = new LineSegments(geometry, material);
    const group = new Group();
    group.name = "frustum";
    group.add(lines);
    function update(vFovDeg, aspect2, depth = 2.5) {
      const vHalf = Math.tan(MathUtils.degToRad(vFovDeg) / 2) * depth;
      const hHalf = vHalf * aspect2;
      const corners = [
        [-hHalf, -vHalf, -depth],
        [hHalf, -vHalf, -depth],
        [hHalf, vHalf, -depth],
        [-hHalf, vHalf, -depth]
      ];
      const verts = [];
      corners.forEach((p, i) => {
        const n = corners[(i + 1) % 4];
        verts.push(0, 0, 0, ...p);
        verts.push(...p, ...n);
      });
      geometry.setFromPoints(verts.map((v) => new Vector3(v[0], v[1], v[2])));
    }
    function setVisible(v) {
      group.visible = v;
    }
    function setColor(hex) {
      material.color.setHex(hex);
    }
    return { group, update, setVisible, setColor };
  }

