          this.renderer.setViewport(vp.x * dpr, vp.y * dpr, vp.width * dpr, vp.height * dpr);
          this.renderer.setScissorTest(false);
          this.renderer.setViewport(0, 0, this.renderer.domElement.width, this.renderer.domElement.height);
